@startuml

class WebPortal {
  +versionNumber : string
  +urlAddress : string
}

class Building {
  +id : string
  +name : string
  +energyClass : EnergyClass
  +address : string
  +yearOfConstruction : int
}

class Entry {
  +name : string
}

class TextEntry extends Entry {}

class NumericEntry extends Entry {}

class Image {
  +fileName : string
}

class Comment {}

class User {
  +userName : string
  +emailAddress : string
  +password : string
}

class Administrator extends User {
  +idCardNumber : string
}

enum EnergyClass {
  A
  B
  C
  D
}

WebPortal "1" -- "*" Building
WebPortal "1" -- "*" User
User "1" -- "*" Building : owner
User "1" -- "*" Comment : author
Building "1" *-- "*" Entry
Building "1" -- "*" Image
Building "1" -- "1" Image : profilePhoto
Building "1" -- "*" Comment

@enduml

